def prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def solve_problem():
    results = []
    for n in range(11):
        D_n = n**3 + 4*n**2 + 6*n + 4

        # Check divisibility: D(n) divides 20^(n+1)
        # We need to check if 20^(n+1) % D_n == 0

        # Since D_n can be larger than 20^(n+1) (though unlikely for small n), 
        # a direct check is best, or use modular arithmetic.
        # Since we are only going up to n=10, D_n is manageable (max D(10) = 1000 + 400 + 60 + 4 = 1464).
        # 20^11 is huge, but we are checking for divisibility, not calculating the full value.

        # Divisibility check: All prime factors of D_n must be among {2, 5}.

        factors = prime_factorization(D_n)

        divides = True
        for p in factors:
            if p != 2 and p != 5:
                divides = False
                break

        factor_str = "{" + ", ".join(f"{p}^{e}" for p, e in factors.items()) + "}"

        results.append({
            'n': n,
            'D(n)': D_n,
            'divides': divides,
            'factorization': factor_str
        })

    for res in results:
        print(f"n={res['n']}: D(n)={res['D(n)']}, Divides 20^(n+1)={res['divides']}, Factorization={res['factorization']}")

solve_problem()

