import math

def check_2_5(k):
    if k <= 0:
        return False
    temp = k
    while temp > 1:
        if temp % 2 != 0 and temp % 5 != 0:
            return False
        temp //= 2
        temp //= 5
    return True

print("Testing m from 1 to 50:")
solutions = []
for m in range(1, 51):
    k = m*m + 1
    if check_2_5(k):
        solutions.append(m)
        print(f"m={m}: k={k} is a solution.")

print("\nFound solutions for m (n+1):", solutions)

def check_2_5_corrected(k):
    if k <= 0:
        return False

    # Remove all factors of 2
    while k % 2 == 0:
        k //= 2

    # Remove all factors of 5
    while k % 5 == 0:
        k //= 5

    # If k is 1, it only had prime factors 2 and 5
    return k == 1

print("Testing m from 1 to 100:")
solutions = []
for m in range(1, 101):
    k = m*m + 1
    if check_2_5_corrected(k):
        solutions.append(m)
        print(f"m={m}: k={k} is a solution.")

